values
  ('a862079f-f338-4690-9108-0e1612193c53', 'a7f0f4a4-e459-489e-b589-6730df97b46b', null, 'topic'::public.curated_course_node_type, 'Algebraic proof and examples', 'This module establishes algebraic proof and examples as the course''s first working framework. It supplies the language and representations needed before the path advances to groups and subgroups.', 0),
  ('4c9f381e-5e58-4d69-acbb-d11afa8b402c', 'a7f0f4a4-e459-489e-b589-6730df97b46b', 'a862079f-f338-4690-9108-0e1612193c53', 'subtopic'::public.curated_course_node_type, 'Operations', 'Operations identifies a specific object, distinction, or relationship within algebraic proof and examples. Learners need to recognize and use it before combining this module''s ideas in later work. It appears before closure because that next topic assumes this starting point.', 0),
  ('c3491794-fda0-4a52-993b-d8a3e670c4aa', 'a7f0f4a4-e459-489e-b589-6730df97b46b', 'a862079f-f338-4690-9108-0e1612193c53', 'subtopic'::public.curated_course_node_type, 'Closure', 'Closure identifies a specific object, distinction, or relationship within algebraic proof and examples. Learners need to recognize and use it before combining this module''s ideas in later work. After operations, closure supplies what is needed to address structures.', 1),
  ('35df2a66-03f1-4eb8-86a9-e41f1bfb20e7', 'a7f0f4a4-e459-489e-b589-6730df97b46b', 'a862079f-f338-4690-9108-0e1612193c53', 'subtopic'::public.curated_course_node_type, 'Structures', 'Structures identifies a specific object, distinction, or relationship within algebraic proof and examples. Learners need to recognize and use it before combining this module''s ideas in later work. After closure, structures supplies what is needed to address counterexamples.', 2),
  ('198c555e-5e80-4655-911a-86cf76275955', 'a7f0f4a4-e459-489e-b589-6730df97b46b', 'a862079f-f338-4690-9108-0e1612193c53', 'subtopic'::public.curated_course_node_type, 'Counterexamples', 'Counterexamples identifies a specific object, distinction, or relationship within algebraic proof and examples. Learners need to recognize and use it before combining this module''s ideas in later work. As the final topic in this module, counterexamples carries the completed idea into groups and subgroups.', 3),
  ('31d8b1cb-0f47-4eee-8c3f-c98420bb4ad5', 'a7f0f4a4-e459-489e-b589-6730df97b46b', null, 'topic'::public.curated_course_node_type, 'Groups and subgroups', 'This module builds directly on algebraic proof and examples and develops groups and subgroups. It belongs here because its methods and distinctions are prerequisites for cosets and lagrange’s theorem.', 1),
  ('bff45c98-a4f3-4518-8c3e-16af05cc488b', 'a7f0f4a4-e459-489e-b589-6730df97b46b', '31d8b1cb-0f47-4eee-8c3f-c98420bb4ad5', 'subtopic'::public.curated_course_node_type, 'Cyclic groups', 'Cyclic groups identifies a specific object, distinction, or relationship within groups and subgroups. Learners need to recognize and use it before combining this module''s ideas in later work. It appears before orders because that next topic assumes this starting point.', 0),
  ('2247595c-e150-4ddc-b424-37046421a8c4', 'a7f0f4a4-e459-489e-b589-6730df97b46b', '31d8b1cb-0f47-4eee-8c3f-c98420bb4ad5', 'subtopic'::public.curated_course_node_type, 'Orders', 'Orders identifies a specific object, distinction, or relationship within groups and subgroups. Learners need to recognize and use it before combining this module''s ideas in later work. After cyclic groups, orders supplies what is needed to address generators.', 1),
  ('4cfd9b4d-6088-485c-9fa4-80f66a7a048b', 'a7f0f4a4-e459-489e-b589-6730df97b46b', '31d8b1cb-0f47-4eee-8c3f-c98420bb4ad5', 'subtopic'::public.curated_course_node_type, 'Generators', 'Generators identifies a specific object, distinction, or relationship within groups and subgroups. Learners need to recognize and use it before combining this module''s ideas in later work. After orders, generators supplies what is needed to address permutation groups.', 2),
  ('2e918170-8931-40fc-ad91-b9ff80eb05e7', 'a7f0f4a4-e459-489e-b589-6730df97b46b', '31d8b1cb-0f47-4eee-8c3f-c98420bb4ad5', 'subtopic'::public.curated_course_node_type, 'Permutation groups', 'Permutation groups identifies a specific object, distinction, or relationship within groups and subgroups. Learners need to recognize and use it before combining this module''s ideas in later work. As the final topic in this module, permutation groups carries the completed idea into cosets and lagrange’s theorem.', 3),
  ('679d54e7-3b5c-4f8e-a6cc-0aed8e78eb49', 'a7f0f4a4-e459-489e-b589-6730df97b46b', null, 'topic'::public.curated_course_node_type, 'Cosets and Lagrange’s theorem', 'This module builds directly on groups and subgroups and develops cosets and lagrange’s theorem. It belongs here because its methods and distinctions are prerequisites for homomorphisms and quotients.', 2),
  ('64ad04cc-a466-42da-a40a-e8a3f3fa8f96', 'a7f0f4a4-e459-489e-b589-6730df97b46b', '679d54e7-3b5c-4f8e-a6cc-0aed8e78eb49', 'subtopic'::public.curated_course_node_type, 'Indices', 'Indices identifies a specific object, distinction, or relationship within cosets and lagrange’s theorem. Learners need to recognize and use it before combining this module''s ideas in later work. It appears before consequences because that next topic assumes this starting point.', 0),
  ('5abdd5c7-1c33-4b2a-91ad-79d7dab50d76', 'a7f0f4a4-e459-489e-b589-6730df97b46b', '679d54e7-3b5c-4f8e-a6cc-0aed8e78eb49', 'subtopic'::public.curated_course_node_type, 'Consequences', 'Consequences identifies a specific object, distinction, or relationship within cosets and lagrange’s theorem. Learners need to recognize and use it before combining this module''s ideas in later work. After indices, consequences supplies what is needed to address modular arithmetic links.', 1),
  ('ded641fe-db44-4ee1-9ac0-f31095e81539', 'a7f0f4a4-e459-489e-b589-6730df97b46b', '679d54e7-3b5c-4f8e-a6cc-0aed8e78eb49', 'subtopic'::public.curated_course_node_type, 'Modular arithmetic links', 'Modular arithmetic links identifies a specific object, distinction, or relationship within cosets and lagrange’s theorem. Learners need to recognize and use it before combining this module''s ideas in later work. As the final topic in this module, modular arithmetic links carries the completed idea into homomorphisms and quotients.', 2),
  ('b3eb865a-f99b-4889-983f-99760d1b08f9', 'a7f0f4a4-e459-489e-b589-6730df97b46b', null, 'topic'::public.curated_course_node_type, 'Homomorphisms and quotients', 'This module builds directly on cosets and lagrange’s theorem and develops homomorphisms and quotients. It belongs here because its methods and distinctions are prerequisites for group actions.', 3),
  ('b3afe332-67e9-4e50-a778-29834284a5bf', 'a7f0f4a4-e459-489e-b589-6730df97b46b', 'b3eb865a-f99b-4889-983f-99760d1b08f9', 'subtopic'::public.curated_course_node_type, 'Kernels', 'Kernels identifies a specific object, distinction, or relationship within homomorphisms and quotients. Learners need to recognize and use it before combining this module''s ideas in later work. It appears before normal subgroups because that next topic assumes this starting point.', 0),
  ('ba3afe88-879a-4f12-8dd7-a1147ff93ad1', 'a7f0f4a4-e459-489e-b589-6730df97b46b', 'b3eb865a-f99b-4889-983f-99760d1b08f9', 'subtopic'::public.curated_course_node_type, 'Normal subgroups', 'Normal subgroups identifies a specific object, distinction, or relationship within homomorphisms and quotients. Learners need to recognize and use it before combining this module''s ideas in later work. After kernels, normal subgroups supplies what is needed to address isomorphism theorems.', 1),
  ('352d4919-a116-4900-a3a4-d85488f0de49', 'a7f0f4a4-e459-489e-b589-6730df97b46b', 'b3eb865a-f99b-4889-983f-99760d1b08f9', 'subtopic'::public.curated_course_node_type, 'Isomorphism theorems', 'Isomorphism theorems provides a formal guarantee or inference rule for homomorphisms and quotients, allowing later conclusions to be justified rather than inferred from examples alone. As the final topic in this module, isomorphism theorems carries the completed idea into group actions.', 2),
  ('bc0e8882-c319-40ee-a91e-535ec1b78571', 'a7f0f4a4-e459-489e-b589-6730df97b46b', null, 'topic'::public.curated_course_node_type, 'Group actions', 'This module builds directly on homomorphisms and quotients and develops group actions. It belongs here because its methods and distinctions are prerequisites for structure of finite groups.', 4),
  ('261ad0ed-54b5-416c-aa11-f6c1190c1b19', 'a7f0f4a4-e459-489e-b589-6730df97b46b', 'bc0e8882-c319-40ee-a91e-535ec1b78571', 'subtopic'::public.curated_course_node_type, 'Orbits', 'Orbits identifies a specific object, distinction, or relationship within group actions. Learners need to recognize and use it before combining this module''s ideas in later work. It appears before stabilizers because that next topic assumes this starting point.', 0),
  ('181dc658-7056-4a13-b26b-be07d25c3d9d', 'a7f0f4a4-e459-489e-b589-6730df97b46b', 'bc0e8882-c319-40ee-a91e-535ec1b78571', 'subtopic'::public.curated_course_node_type, 'Stabilizers', 'Stabilizers identifies a specific object, distinction, or relationship within group actions. Learners need to recognize and use it before combining this module''s ideas in later work. After orbits, stabilizers supplies what is needed to address class equation.', 1),
  ('7ba0f444-d32b-4240-9710-a5529b1b4406', 'a7f0f4a4-e459-489e-b589-6730df97b46b', 'bc0e8882-c319-40ee-a91e-535ec1b78571', 'subtopic'::public.curated_course_node_type, 'Class equation', 'Class equation identifies a specific object, distinction, or relationship within group actions. Learners need to recognize and use it before combining this module''s ideas in later work. After stabilizers, class equation supplies what is needed to address counting with burnside.', 2),
  ('bba2745e-1ea2-4728-aa16-b23c6c507460', 'a7f0f4a4-e459-489e-b589-6730df97b46b', 'bc0e8882-c319-40ee-a91e-535ec1b78571', 'subtopic'::public.curated_course_node_type, 'Counting with Burnside', 'Counting with Burnside identifies a specific object, distinction, or relationship within group actions. Learners need to recognize and use it before combining this module''s ideas in later work. As the final topic in this module, counting with burnside carries the completed idea into structure of finite groups.', 3),
  ('bf37a532-ef95-47dd-b0da-85d2223dfeb7', 'a7f0f4a4-e459-489e-b589-6730df97b46b', null, 'topic'::public.curated_course_node_type, 'Structure of finite groups', 'This module builds directly on group actions and develops structure of finite groups. It belongs here because its methods and distinctions are prerequisites for rings and integral domains.', 5),
  ('341babdf-f50b-44ad-92fa-a9b885739971', 'a7f0f4a4-e459-489e-b589-6730df97b46b', 'bf37a532-ef95-47dd-b0da-85d2223dfeb7', 'subtopic'::public.curated_course_node_type, 'Sylow theorems', 'Sylow theorems provides a formal guarantee or inference rule for structure of finite groups, allowing later conclusions to be justified rather than inferred from examples alone. It appears before direct products because that next topic assumes this starting point.', 0),
  ('b34558da-724f-4af2-b2d6-15eee3d39254', 'a7f0f4a4-e459-489e-b589-6730df97b46b', 'bf37a532-ef95-47dd-b0da-85d2223dfeb7', 'subtopic'::public.curated_course_node_type, 'Direct products', 'Direct products identifies a specific object, distinction, or relationship within structure of finite groups. Learners need to recognize and use it before combining this module''s ideas in later work. After sylow theorems, direct products supplies what is needed to address classification examples.', 1),
  ('b2266e99-debc-4eb7-93bb-60a63a006ed9', 'a7f0f4a4-e459-489e-b589-6730df97b46b', 'bf37a532-ef95-47dd-b0da-85d2223dfeb7', 'subtopic'::public.curated_course_node_type, 'Classification examples', 'Classification examples identifies a specific object, distinction, or relationship within structure of finite groups. Learners need to recognize and use it before combining this module''s ideas in later work. As the final topic in this module, classification examples carries the completed idea into rings and integral domains.', 2),
  ('ed69f77d-5ec4-4286-b29c-2aa807eae722', 'a7f0f4a4-e459-489e-b589-6730df97b46b', null, 'topic'::public.curated_course_node_type, 'Rings and integral domains', 'This module builds directly on structure of finite groups and develops rings and integral domains. It belongs here because its methods and distinctions are prerequisites for ideals and quotient rings.', 6),
  ('ecc45d42-3e53-4198-8f0f-10746d90065b', 'a7f0f4a4-e459-489e-b589-6730df97b46b', 'ed69f77d-5ec4-4286-b29c-2aa807eae722', 'subtopic'::public.curated_course_node_type, 'Units', 'Units identifies a specific object, distinction, or relationship within rings and integral domains. Learners need to recognize and use it before combining this module''s ideas in later work. It appears before zero divisors because that next topic assumes this starting point.', 0),
  ('838c9eab-f199-4ff6-8566-d61f2c918264', 'a7f0f4a4-e459-489e-b589-6730df97b46b', 'ed69f77d-5ec4-4286-b29c-2aa807eae722', 'subtopic'::public.curated_course_node_type, 'Zero divisors', 'Zero divisors identifies a specific object, distinction, or relationship within rings and integral domains. Learners need to recognize and use it before combining this module''s ideas in later work. After units, zero divisors supplies what is needed to address subrings.', 1),
  ('9dfe8921-3775-4a18-bd4b-5d95f68320dc', 'a7f0f4a4-e459-489e-b589-6730df97b46b', 'ed69f77d-5ec4-4286-b29c-2aa807eae722', 'subtopic'::public.curated_course_node_type, 'Subrings', 'Subrings identifies a specific object, distinction, or relationship within rings and integral domains. Learners need to recognize and use it before combining this module''s ideas in later work. After zero divisors, subrings supplies what is needed to address characteristic.', 2),
  ('5e185e85-a659-4e5c-9ab5-4282083a9cb0', 'a7f0f4a4-e459-489e-b589-6730df97b46b', 'ed69f77d-5ec4-4286-b29c-2aa807eae722', 'subtopic'::public.curated_course_node_type, 'Characteristic', 'Characteristic identifies a specific object, distinction, or relationship within rings and integral domains. Learners need to recognize and use it before combining this module''s ideas in later work. As the final topic in this module, characteristic carries the completed idea into ideals and quotient rings.', 3),
  ('7ee72224-baf4-4aca-92da-25143d7b516c', 'a7f0f4a4-e459-489e-b589-6730df97b46b', null, 'topic'::public.curated_course_node_type, 'Ideals and quotient rings', 'This module builds directly on rings and integral domains and develops ideals and quotient rings. It belongs here because its methods and distinctions are prerequisites for divisibility in rings.', 7),
  ('26d7fc05-a5fe-42cb-92df-bfc574502d6d', 'a7f0f4a4-e459-489e-b589-6730df97b46b', '7ee72224-baf4-4aca-92da-25143d7b516c', 'subtopic'::public.curated_course_node_type, 'Prime/maximal ideals', 'Prime/maximal ideals identifies a specific object, distinction, or relationship within ideals and quotient rings. Learners need to recognize and use it before combining this module''s ideas in later work. It appears before ring homomorphisms because that next topic assumes this starting point.', 0),
  ('a8e73b36-3a11-4f1b-82a8-d9a4ab9c20ce', 'a7f0f4a4-e459-489e-b589-6730df97b46b', '7ee72224-baf4-4aca-92da-25143d7b516c', 'subtopic'::public.curated_course_node_type, 'Ring homomorphisms', 'Ring homomorphisms identifies a specific object, distinction, or relationship within ideals and quotient rings. Learners need to recognize and use it before combining this module''s ideas in later work. After prime/maximal ideals, ring homomorphisms supplies what is needed to address crt.', 1),
  ('b84b6b29-e305-4de0-916e-8d29d5f45e14', 'a7f0f4a4-e459-489e-b589-6730df97b46b', '7ee72224-baf4-4aca-92da-25143d7b516c', 'subtopic'::public.curated_course_node_type, 'CRT', 'CRT identifies a specific object, distinction, or relationship within ideals and quotient rings. Learners need to recognize and use it before combining this module''s ideas in later work. As the final topic in this module, crt carries the completed idea into divisibility in rings.', 2),
  ('fe892bd5-24e9-4afe-98c2-8c35b7c8fad8', 'a7f0f4a4-e459-489e-b589-6730df97b46b', null, 'topic'::public.curated_course_node_type, 'Divisibility in rings', 'This module builds directly on ideals and quotient rings and develops divisibility in rings. It belongs here because its methods and distinctions are prerequisites for polynomial rings.', 8),
  ('0cd796e2-e640-48ca-a340-4713ace29929', 'a7f0f4a4-e459-489e-b589-6730df97b46b', 'fe892bd5-24e9-4afe-98c2-8c35b7c8fad8', 'subtopic'::public.curated_course_node_type, 'Euclidean domains', 'Euclidean domains identifies a specific object, distinction, or relationship within divisibility in rings. Learners need to recognize and use it before combining this module''s ideas in later work. It appears before pids because that next topic assumes this starting point.', 0),
  ('ef7a9ca5-452c-4949-88ad-917ffc57ace6', 'a7f0f4a4-e459-489e-b589-6730df97b46b', 'fe892bd5-24e9-4afe-98c2-8c35b7c8fad8', 'subtopic'::public.curated_course_node_type, 'PIDs', 'PIDs identifies a specific object, distinction, or relationship within divisibility in rings. Learners need to recognize and use it before combining this module''s ideas in later work. After euclidean domains, pids supplies what is needed to address ufds.', 1),
  ('c39af98b-37dd-4e6c-ab7b-46d984ab0175', 'a7f0f4a4-e459-489e-b589-6730df97b46b', 'fe892bd5-24e9-4afe-98c2-8c35b7c8fad8', 'subtopic'::public.curated_course_node_type, 'UFDs', 'UFDs identifies a specific object, distinction, or relationship within divisibility in rings. Learners need to recognize and use it before combining this module''s ideas in later work. After pids, ufds supplies what is needed to address irreducibles.', 2);
