values
  ('352e0f8c-af02-4cf9-8f07-d1da4b070f0b', 'a7f0f4a4-e459-489e-b589-6730df97b46b', 'fe892bd5-24e9-4afe-98c2-8c35b7c8fad8', 'subtopic'::public.curated_course_node_type, 'Irreducibles', 'Irreducibles identifies a specific object, distinction, or relationship within divisibility in rings. Learners need to recognize and use it before combining this module''s ideas in later work. As the final topic in this module, irreducibles carries the completed idea into polynomial rings.', 3),
  ('30bb9696-f7b4-4b3c-8a62-1cb7fe1aad3e', 'a7f0f4a4-e459-489e-b589-6730df97b46b', null, 'topic'::public.curated_course_node_type, 'Polynomial rings', 'This module builds directly on divisibility in rings and develops polynomial rings. It belongs here because its methods and distinctions are prerequisites for fields and extensions.', 9),
  ('35c264e3-c7f0-425d-a9fc-7871a1bce1d8', 'a7f0f4a4-e459-489e-b589-6730df97b46b', '30bb9696-f7b4-4b3c-8a62-1cb7fe1aad3e', 'subtopic'::public.curated_course_node_type, 'Division', 'Division identifies a specific object, distinction, or relationship within polynomial rings. Learners need to recognize and use it before combining this module''s ideas in later work. It appears before factorization because that next topic assumes this starting point.', 0),
  ('fff82ad3-4653-4263-b8fa-e9c7666dc402', 'a7f0f4a4-e459-489e-b589-6730df97b46b', '30bb9696-f7b4-4b3c-8a62-1cb7fe1aad3e', 'subtopic'::public.curated_course_node_type, 'Factorization', 'Factorization identifies a specific object, distinction, or relationship within polynomial rings. Learners need to recognize and use it before combining this module''s ideas in later work. After division, factorization supplies what is needed to address irreducibility criteria.', 1),
  ('23bf3fc3-fda5-496e-baa0-ab8465b30607', 'a7f0f4a4-e459-489e-b589-6730df97b46b', '30bb9696-f7b4-4b3c-8a62-1cb7fe1aad3e', 'subtopic'::public.curated_course_node_type, 'Irreducibility criteria', 'Irreducibility criteria identifies a specific object, distinction, or relationship within polynomial rings. Learners need to recognize and use it before combining this module''s ideas in later work. After factorization, irreducibility criteria supplies what is needed to address roots.', 2),
  ('db9c3e20-cdcf-49f4-a746-2569f2c8623a', 'a7f0f4a4-e459-489e-b589-6730df97b46b', '30bb9696-f7b4-4b3c-8a62-1cb7fe1aad3e', 'subtopic'::public.curated_course_node_type, 'Roots', 'Roots identifies a specific object, distinction, or relationship within polynomial rings. Learners need to recognize and use it before combining this module''s ideas in later work. As the final topic in this module, roots carries the completed idea into fields and extensions.', 3),
  ('5f645643-bc6a-4d5d-8348-8b1ea4f37b42', 'a7f0f4a4-e459-489e-b589-6730df97b46b', null, 'topic'::public.curated_course_node_type, 'Fields and extensions', 'This module builds directly on polynomial rings and develops fields and extensions. It belongs here because its methods and distinctions are prerequisites for finite fields and galois preview.', 10),
  ('b55baa8c-296d-42ec-b1ee-9b5f9aba5070', 'a7f0f4a4-e459-489e-b589-6730df97b46b', '5f645643-bc6a-4d5d-8348-8b1ea4f37b42', 'subtopic'::public.curated_course_node_type, 'Vector-space degree', 'Vector-space degree gives fields and extensions a reusable representation for organizing assumptions, variables, and relationships before analysis begins. It appears before algebraic elements because that next topic assumes this starting point.', 0),
  ('edd6d21a-3515-486c-8b18-58aa62e374f7', 'a7f0f4a4-e459-489e-b589-6730df97b46b', '5f645643-bc6a-4d5d-8348-8b1ea4f37b42', 'subtopic'::public.curated_course_node_type, 'Algebraic elements', 'Algebraic elements identifies a specific object, distinction, or relationship within fields and extensions. Learners need to recognize and use it before combining this module''s ideas in later work. After vector-space degree, algebraic elements supplies what is needed to address splitting fields.', 1),
  ('b985c35c-c444-49e4-9a6d-a91ad033b340', 'a7f0f4a4-e459-489e-b589-6730df97b46b', '5f645643-bc6a-4d5d-8348-8b1ea4f37b42', 'subtopic'::public.curated_course_node_type, 'Splitting fields', 'Splitting fields identifies a specific object, distinction, or relationship within fields and extensions. Learners need to recognize and use it before combining this module''s ideas in later work. As the final topic in this module, splitting fields carries the completed idea into finite fields and galois preview.', 2),
  ('5391a6de-0f0d-482e-b2b3-c8aacdd02cde', 'a7f0f4a4-e459-489e-b589-6730df97b46b', null, 'topic'::public.curated_course_node_type, 'Finite fields and Galois preview', 'This culminating module draws on fields and extensions and develops finite fields and galois preview. It belongs last because it requires the earlier tools to be selected, combined, and evaluated rather than used one at a time.', 11),
  ('336da876-c7b3-4b95-92ba-9dd08eafd7b1', 'a7f0f4a4-e459-489e-b589-6730df97b46b', '5391a6de-0f0d-482e-b2b3-c8aacdd02cde', 'subtopic'::public.curated_course_node_type, 'Construction', 'Construction identifies a specific object, distinction, or relationship within finite fields and galois preview. Learners need to recognize and use it before combining this module''s ideas in later work. It appears before frobenius because that next topic assumes this starting point.', 0),
